"""
Question Bank Service for Interview AI.

Organized cleanly by Role -> Type (Technical / HR) -> Difficulty Level
(Beginner / Intermediate / Advanced). Every (role, level) bucket provides
at least 25 distinct, non-repeating questions with expected keywords and
model answer hints for evaluation.

Adding a new role is as simple as adding an entry to ROLE_OPTIONS and
TECH_QUESTIONS.
"""

import math
import random
from typing import Dict, List

ROLE_OPTIONS = [
    "Web Developer",
    "Software Developer",
    "Data Analyst",
    "Python Developer",
    "Full Stack Developer",
    "AI/ML Engineer",
    "HR/Other",
]

LEVEL_OPTIONS = ["Beginner", "Intermediate", "Advanced"]
TYPE_OPTIONS = ["Technical", "HR", "Mixed"]
QUESTION_COUNT_OPTIONS = [5, 10, 20]


def _q(question: str, keywords: List[str], ideal_answer: str, category: str = "Technical") -> Dict:
    return {
        "question": question,
        "keywords": keywords,
        "ideal_answer": ideal_answer,
        "category": category,
    }


