# Build additional roles cleanly with >= 25 distinct, role-authentic questions per level!
# Let's add Data/Web/Python/Software overlap? No—let's give AI/ML, Web, Software, Data, HR/Other,
# AND dedicated distinct banks for "Python Developer" (already done!) and "Full Stack Developer" (already done!)
# Wait—let's verify all 7 roles in TECH_QUESTIONS!
# Right now we wrote:
# 1. "Web Developer" (25 B, 25 I, 25 A)
# 2. "Software Developer" (25 B, 25 I, 25 A)
# 3. "Data Analyst" (25 B, 25 I, 25 A)
# 4. "Python Developer" (25 B, 25 I, 25 A)
# 5. "Full Stack Developer" (25 B, 25 I, 25 A)
# 6. "AI/ML Engineer" (25 B, 25 I, 25 A)
# 7. "HR/Other" (25 B, 25 I, 25 A)
# All 7 roles x 3 levels x 25 questions + 3 HR levels x 26 questions = 603 unique curated questions!


def get_questions(role: str, q_type: str, level: str, count: int) -> List[Dict]:
    """
    Randomly select `count` unique non-repeating questions for the given
    role, question type (Technical / HR / Mixed), and difficulty level.
    """
    if role not in ROLE_OPTIONS:
        role = "Software Developer"
    if level not in LEVEL_OPTIONS:
        level = "Intermediate"
    if q_type not in TYPE_OPTIONS:
        q_type = "Mixed"

    tech_pool = list(TECH_QUESTIONS.get(role, TECH_QUESTIONS["Software Developer"]).get(level, []))
    hr_pool = list(HR_QUESTIONS.get(level, HR_QUESTIONS["Intermediate"]))

    selected: List[Dict] = []

    if q_type == "Technical":
        random.shuffle(tech_pool)
        selected = tech_pool[:count]
    elif q_type == "HR":
        random.shuffle(hr_pool)
        selected = hr_pool[:count]
    else:  # Mixed: combine Technical and HR randomly without repeating
        tech_count = math.ceil(count / 2)
        hr_count = count - tech_count
        random.shuffle(tech_pool)
        random.shuffle(hr_pool)
        selected = tech_pool[:tech_count] + hr_pool[:hr_count]
        random.shuffle(selected)

    # Return fresh copies with standardized fields
    return [
        {
            "index": idx,
            "question": item["question"],
            "category": item.get("category", "Technical"),
            "keywords": list(item.get("keywords", [])),
            "ideal_answer": item.get("ideal_answer", ""),
            "answer": "",
            "score": 0,
            "skipped": False,
            "time_spent_seconds": 0,
            "feedback": {},
        }
        for idx, item in enumerate(selected)
    ]
